<?php

namespace App\Support;

/**
 * Wrapper for bilingual text (Indonesian / English).
 *
 * All text generated by the server is returned as an
 * ['id' => ..., 'en' => ...] pair so it can be rendered as data-id / data-en
 * attributes and handled by the client-side language switcher.
 */
class Bi
{
    /**
     * @return array{id: string, en: string}
     */
    public static function of(string $id, string $en): array
    {
        return ['id' => $id, 'en' => $en];
    }

    /**
     * Wrap a list of sentences as a list of bilingual pairs.
     *
     * @param  array<int, array{0: string, 1: string}>  $pairs
     * @return array<int, array{id: string, en: string}>
     */
    public static function many(array $pairs): array
    {
        return array_map(fn (array $pair) => self::of($pair[0], $pair[1]), $pairs);
    }
}
